content = r'<!DOCTYPE html>\n<html lang="en">\n<head>\n<meta charset="UTF-8">\n<meta name="viewport" content="width=device-width, initial-scale=1.0">\n<title>Nitakusaka Report — {{ report.target }}</title>\n<style>\n  :root {\n    --bg:        #0E1428;\n    --bg-deep:   #0A0F20;\n    --bg-card:   #161E3A;\n    --bg-elev:   #1C2647;\n    --border:    #2A3866;\n    --border-lit:#3D4F8A;\n    --text:      #E4E9F7;\n    --text-dim:  #8B97BE;\n    --text-faint:#5A6699;\n\n    --cyan:      #2DE2E6;\n    --violet:    #8B5CF6;\n    --coral:     #FF5C7C;\n    --gold:      #FFC542;\n    --mint:      #3DF5A0;\n\n    --critical:  #FF4365;\n    --high:      #FF8A3D;\n    --medium:    #FFC542;\n    --low:       #2DE2E6;\n    --info:      #8B5CF6;\n\n    --grad-hero: linear-gradient(120deg, #2DE2E6 0%, #8B5CF6 60%, #FF5C7C 100%);\n    --grad-cyan: linear-gradient(135deg, #2DE2E6, #4F8BFF);\n  }\n\n  * { margin: 0; padding: 0; box-sizing: border-box; }\n\n  body {\n    background:\n      radial-gradient(1200px 600px at 80% -10%, rgba(139,92,246,0.18), transparent 60%),\n      radial-gradient(900px 500px at 0% 0%, rgba(45,226,230,0.12), transparent 55%),\n      var(--bg);\n    background-attachment: fixed;\n    color: var(--text);\n    font-family: \'Inter\', -apple-system, BlinkMacSystemFont, \'Segoe UI\', sans-serif;\n    line-height: 1.6;\n  }\n\n  .mono { font-family: \'JetBrains Mono\', \'Fira Code\', monospace; }\n\n  /* ── Header ── */\n  .header {\n    position: relative;\n    padding: 56px 40px 40px;\n    overflow: hidden;\n    border-bottom: 1px solid var(--border);\n  }\n\n  .header::before {\n    content: "";\n    position: absolute;\n    inset: 0;\n    background:\n      repeating-linear-gradient(90deg, transparent, transparent 38px, rgba(61,79,138,0.08) 39px, transparent 40px),\n      repeating-linear-gradient(0deg, transparent, transparent 38px, rgba(61,79,138,0.08) 39px, transparent 40px);\n    pointer-events: none;\n  }\n\n  .header-tag {\n    display: flex; align-items: center; gap: 10px; margin-bottom: 18px;\n    position: relative;\n  }\n\n  .pulse {\n    width: 8px; height: 8px; border-radius: 50%;\n    background: var(--mint);\n    box-shadow: 0 0 0 0 rgba(61,245,160,0.6);\n    animation: pulse 2.4s infinite;\n  }\n\n  @keyframes pulse {\n    0%   { box-shadow: 0 0 0 0 rgba(61,245,160,0.5); }\n    70%  { box-shadow: 0 0 0 10px rgba(61,245,160,0); }\n    100% { box-shadow: 0 0 0 0 rgba(61,245,160,0); }\n  }\n\n  .header-tag span {\n    color: var(--mint); font-size: 11px; letter-spacing: 3.5px;\n    text-transform: uppercase; font-family: \'JetBrains Mono\', monospace;\n  }\n\n  .header h1 {\n    font-size: 54px; font-weight: 800; letter-spacing: -1.5px;\n    line-height: 1; margin-bottom: 14px; position: relative;\n    background: var(--grad-hero);\n    -webkit-background-clip: text; background-clip: text;\n    -webkit-text-fill-color: transparent;\n    width: fit-content;\n  }\n\n  .header .target {\n    display: inline-block; position: relative;\n    font-size: 16px; color: var(--cyan);\n    font-family: \'JetBrains Mono\', monospace;\n    padding: 6px 14px; margin-bottom: 24px;\n    border: 1px solid var(--border-lit); border-radius: 8px;\n    background: rgba(45,226,230,0.06);\n  }\n\n  .header-meta {\n    display: flex; gap: 28px; flex-wrap: wrap; position: relative;\n  }\n  .header-meta div { font-size: 12px; color: var(--text-dim); }\n  .header-meta strong { color: var(--text); font-weight: 600; }\n\n  /* ── Container ── */\n  .container { max-width: 1120px; margin: 0 auto; padding: 44px 40px; }\n  .section { margin-bottom: 52px; }\n\n  .section-title {\n    font-size: 12px; letter-spacing: 2.5px; text-transform: uppercase;\n    color: var(--text-dim); margin-bottom: 22px;\n    font-family: \'JetBrains Mono\', monospace;\n    display: flex; align-items: center; gap: 14px;\n  }\n  .section-title::before {\n    content: ""; width: 22px; height: 2px; border-radius: 2px;\n    background: var(--grad-cyan);\n  }\n  .section-title::after {\n    content: ""; flex: 1; height: 1px;\n    background: linear-gradient(90deg, var(--border), transparent);\n  }\n\n  /* ── Severity cards ── */\n  .severity-grid {\n    display: grid; grid-template-columns: repeat(5, 1fr); gap: 14px;\n  }\n\n  .sev-card {\n    position: relative; border-radius: 14px; padding: 24px 16px;\n    text-align: center; overflow: hidden;\n    background: var(--bg-card);\n    border: 1px solid var(--border);\n    transition: transform 0.2s ease, border-color 0.2s ease;\n  }\n  .sev-card:hover { transform: translateY(-3px); border-color: var(--border-lit); }\n\n  .sev-card::before {\n    content: ""; position: absolute; top: 0; left: 0; right: 0; height: 3px;\n  }\n  .sev-card::after {\n    content: ""; position: absolute; top: -40px; left: 50%; transform: translateX(-50%);\n    width: 90px; height: 90px; border-radius: 50%; opacity: 0.18; filter: blur(26px);\n  }\n  .sev-card.critical::before { background: var(--critical); }\n  .sev-card.high::before     { background: var(--high); }\n  .sev-card.medium::before   { background: var(--medium); }\n  .sev-card.low::before      { background: var(--low); }\n  .sev-card.info::before     { background: var(--info); }\n  .sev-card.critical::after { background: var(--critical); }\n  .sev-card.high::after     { background: var(--high); }\n  .sev-card.medium::after   { background: var(--medium); }\n  .sev-card.low::after      { background: var(--low); }\n  .sev-card.info::after     { background: var(--info); }\n\n  .sev-count {\n    font-size: 40px; font-weight: 800; font-family: \'JetBrains Mono\', monospace;\n    line-height: 1; margin-bottom: 10px; position: relative;\n  }\n  .sev-card.critical .sev-count { color: var(--critical); }\n  .sev-card.high .sev-count     { color: var(--high); }\n  .sev-card.medium .sev-count   { color: var(--medium); }\n  .sev-card.low .sev-count      { color: var(--low); }\n  .sev-card.info .sev-count     { color: var(--info); }\n\n  .sev-label {\n    font-size: 10px; letter-spacing: 1.5px; text-transform: uppercase;\n    color: var(--text-dim); position: relative;\n  }\n\n  /* ── Stats row ── */\n  .stats-row {\n    display: grid; grid-template-columns: repeat(3, 1fr); gap: 16px; margin-top: 16px;\n  }\n  .stat-box {\n    position: relative; border-radius: 14px; padding: 22px 24px;\n    background: var(--bg-card); border: 1px solid var(--border);\n    overflow: hidden;\n  }\n  .stat-box::before {\n    content: ""; position: absolute; left: 0; top: 0; bottom: 0; width: 3px;\n    background: var(--grad-cyan);\n  }\n  .stat-box .num {\n    font-size: 30px; font-weight: 800; font-family: \'JetBrains Mono\', monospace;\n    background: var(--grad-cyan); -webkit-background-clip: text; background-clip: text;\n    -webkit-text-fill-color: transparent; width: fit-content;\n  }\n  .stat-box .lbl { font-size: 12px; color: var(--text-dim); margin-top: 6px; }\n\n  /* ── Findings ── */\n  .finding {\n    border-radius: 14px; margin-bottom: 16px; overflow: hidden;\n    background: var(--bg-card); border: 1px solid var(--border);\n    transition: border-color 0.2s ease;\n  }\n  .finding:hover { border-color: var(--border-lit); }\n\n  .finding-head {\n    display: flex; align-items: center; gap: 14px; padding: 18px 22px;\n    border-left: 4px solid var(--border); position: relative;\n  }\n  .finding.critical .finding-head { border-left-color: var(--critical); }\n  .finding.high .finding-head     { border-left-color: var(--high); }\n  .finding.medium .finding-head   { border-left-color: var(--medium); }\n  .finding.low .finding-head      { border-left-color: var(--low); }\n  .finding.info .finding-head     { border-left-color: var(--info); }\n\n  .sev-badge {\n    font-size: 10px; font-weight: 700; letter-spacing: 1px; padding: 5px 11px;\n    border-radius: 6px; text-transform: uppercase;\n    font-family: \'JetBrains Mono\', monospace; white-space: nowrap;\n  }\n  .finding.critical .sev-badge { background: rgba(255,67,101,0.16);  color: var(--critical); }\n  .finding.high .sev-badge     { background: rgba(255,138,61,0.16);  color: var(--high); }\n  .finding.medium .sev-badge   { background: rgba(255,197,66,0.16);  color: var(--medium); }\n  .finding.low .sev-badge      { background: rgba(45,226,230,0.16);  color: var(--low); }\n  .finding.info .sev-badge     { background: rgba(139,92,246,0.18);  color: var(--info); }\n\n  .finding-title { font-size: 15px; font-weight: 600; color: #FFFFFF; }\n  .finding-body { padding: 0 22px 20px 26px; }\n  .finding-detail { font-size: 13px; color: var(--text); margin-bottom: 14px; }\n\n  .finding-field { font-size: 12px; margin-top: 8px; display: flex; gap: 10px; }\n  .finding-field .key {\n    color: var(--text-faint); text-transform: uppercase; letter-spacing: 1px; min-width: 110px;\n  }\n  .finding-field .val { color: var(--text); font-family: \'JetBrains Mono\', monospace; word-break: break-all; }\n  .finding-field .val.cve { color: var(--high); }\n  .finding-field .val.fix { color: var(--mint); font-family: \'Inter\', sans-serif; }\n\n  /* ── Tables ── */\n  table {\n    width: 100%; border-collapse: collapse; border-radius: 14px; overflow: hidden;\n    background: var(--bg-card); border: 1px solid var(--border);\n  }\n  th {\n    text-align: left; padding: 13px 20px; font-size: 11px; letter-spacing: 1px;\n    text-transform: uppercase; color: var(--cyan);\n    background: var(--bg-elev); border-bottom: 1px solid var(--border); font-weight: 600;\n  }\n  td { padding: 12px 20px; font-size: 13px; border-bottom: 1px solid var(--border); color: var(--text); }\n  tr:last-child td { border-bottom: none; }\n  tr:hover td { background: rgba(45,226,230,0.04); }\n  td.mono { font-family: \'JetBrains Mono\', monospace; }\n  .risk-flag { color: var(--critical); font-size: 12px; }\n\n  /* ── Tech chips ── */\n  .chips { display: flex; flex-wrap: wrap; gap: 10px; }\n  .chip {\n    border-radius: 8px; padding: 7px 15px; font-size: 12px; color: var(--text);\n    font-family: \'JetBrains Mono\', monospace;\n    background: rgba(139,92,246,0.10); border: 1px solid var(--border-lit);\n    transition: transform 0.15s ease;\n  }\n  .chip:hover { transform: translateY(-2px); }\n\n  /* ── Empty state ── */\n  .empty {\n    color: var(--text-faint); font-size: 13px; font-style: italic;\n    padding: 24px; text-align: center; border-radius: 14px;\n    background: var(--bg-card); border: 1px dashed var(--border);\n  }\n\n  /* ── Footer ── */\n  .footer {\n    border-top: 1px solid var(--border); padding: 30px 40px; text-align: center;\n    color: var(--text-faint); font-size: 12px;\n  }\n  .footer .brand {\n    font-family: \'JetBrains Mono\', monospace; font-weight: 700;\n    background: var(--grad-hero); -webkit-background-clip: text; background-clip: text;\n    -webkit-text-fill-color: transparent;\n  }\n\n  @media (prefers-reduced-motion: reduce) {\n    .pulse { animation: none; }\n    .sev-card, .chip, .finding { transition: none; }\n  }\n\n  @media (max-width: 700px) {\n    .severity-grid { grid-template-columns: repeat(2, 1fr); }\n    .stats-row { grid-template-columns: 1fr; }\n    .header h1 { font-size: 38px; }\n    .container { padding: 28px 22px; }\n  }\n</style>\n</head>\n<body>\n\n  <div class="header">\n    <div class="header-tag">\n      <div class="pulse"></div>\n      <span>Reconnaissance Report</span>\n    </div>\n    <h1>Nitakusaka</h1>\n    <div class="target mono">{{ report.target }}</div>\n    <div class="header-meta">\n      <div>Generated <strong>{{ report.generated }}</strong></div>\n      <div>Engine <strong>v{{ report.version }}</strong></div>\n      <div>Findings <strong>{{ report.total_findings }}</strong></div>\n    </div>\n  </div>\n\n  <div class="container">\n\n    <div class="section">\n      <div class="section-title">Executive Summary</div>\n      <div class="severity-grid">\n        <div class="sev-card critical">\n          <div class="sev-count">{{ report.severity_counts.CRITICAL }}</div>\n          <div class="sev-label">Critical</div>\n        </div>\n        <div class="sev-card high">\n          <div class="sev-count">{{ report.severity_counts.HIGH }}</div>\n          <div class="sev-label">High</div>\n        </div>\n        <div class="sev-card medium">\n          <div class="sev-count">{{ report.severity_counts.MEDIUM }}</div>\n          <div class="sev-label">Medium</div>\n        </div>\n        <div class="sev-card low">\n          <div class="sev-count">{{ report.severity_counts.LOW }}</div>\n          <div class="sev-label">Low</div>\n        </div>\n        <div class="sev-card info">\n          <div class="sev-count">{{ report.severity_counts.INFO }}</div>\n          <div class="sev-label">Info</div>\n        </div>\n      </div>\n      <div class="stats-row">\n        <div class="stat-box">\n          <div class="num">{{ report.total_subdomains }}</div>\n          <div class="lbl">Subdomains discovered</div>\n        </div>\n        <div class="stat-box">\n          <div class="num">{{ report.total_ports }}</div>\n          <div class="lbl">Open ports found</div>\n        </div>\n        <div class="stat-box">\n          <div class="num">{{ report.technologies | length }}</div>\n          <div class="lbl">Technologies detected</div>\n        </div>\n      </div>\n    </div>\n\n    <div class="section">\n      <div class="section-title">Findings</div>\n      {% if report.findings %}\n        {% for finding in report.findings %}\n        <div class="finding {{ finding.severity | lower }}">\n          <div class="finding-head">\n            <span class="sev-badge">{{ finding.severity }}</span>\n            <span class="finding-title">{{ finding.title }}</span>\n          </div>\n          <div class="finding-body">\n            {% if finding.detail %}\n            <div class="finding-detail">{{ finding.detail }}</div>\n            {% endif %}\n            {% if finding.url %}\n            <div class="finding-field">\n              <span class="key">Location</span>\n              <span class="val">{{ finding.url }}</span>\n            </div>\n            {% endif %}\n            {% if finding.cve %}\n            <div class="finding-field">\n              <span class="key">CVE</span>\n              <span class="val cve">\n                {% if finding.cve is string %}{{ finding.cve }}{% else %}{{ finding.cve | join(\', \') }}{% endif %}\n              </span>\n            </div>\n            {% endif %}\n            {% if finding.recommendation %}\n            <div class="finding-field">\n              <span class="key">Remediation</span>\n              <span class="val fix">{{ finding.recommendation }}</span>\n            </div>\n            {% endif %}\n          </div>\n        </div>\n        {% endfor %}\n      {% else %}\n        <div class="empty">No findings identified in this scan.</div>\n      {% endif %}\n    </div>\n\n    <div class="section">\n      <div class="section-title">Discovered Subdomains</div>\n      {% if report.subdomains %}\n      <table>\n        <thead><tr><th>Subdomain</th><th>IP Addresses</th><th>Source</th></tr></thead>\n        <tbody>\n          {% for sub in report.subdomains %}\n          <tr>\n            <td class="mono">{{ sub.subdomain }}</td>\n            <td class="mono">{{ sub.ips or \'—\' }}</td>\n            <td>{{ sub.status }}</td>\n          </tr>\n          {% endfor %}\n        </tbody>\n      </table>\n      {% else %}\n        <div class="empty">No subdomains discovered.</div>\n      {% endif %}\n    </div>\n\n    <div class="section">\n      <div class="section-title">Open Ports &amp; Services</div>\n      {% if report.open_ports %}\n      <table>\n        <thead><tr><th>Port</th><th>Service</th><th>Risk Assessment</th></tr></thead>\n        <tbody>\n          {% for port in report.open_ports %}\n          <tr>\n            <td class="mono">{{ port.port }}</td>\n            <td>{{ port.service }}</td>\n            <td>{% if port.risk %}<span class="risk-flag">⚠ {{ port.risk }}</span>{% else %}—{% endif %}</td>\n          </tr>\n          {% endfor %}\n        </tbody>\n      </table>\n      {% else %}\n        <div class="empty">No open ports found.</div>\n      {% endif %}\n    </div>\n\n    <div class="section">\n      <div class="section-title">Detected Technologies</div>\n      {% if report.technologies %}\n      <div class="chips">\n        {% for tech in report.technologies %}\n        <span class="chip">{{ tech }}</span>\n        {% endfor %}\n      </div>\n      {% else %}\n        <div class="empty">No technologies fingerprinted.</div>\n      {% endif %}\n    </div>\n\n  </div>\n\n  <div class="footer">\n    Generated by <span class="brand">Nitakusaka</span> — automated offensive reconnaissance framework\n  </div>\n\n</body>\n</html>\n'
import os
os.makedirs("templates", exist_ok=True)
with open("templates/report.html.j2", "w", encoding="utf-8") as f:
    f.write(content)
print("New template written:", len(content), "chars")
